/**
 * Regenerate src/lib/openings.data.ts from the lichess opening book.
 *
 * Run by hand when the book should be refreshed; the generated file is
 * committed, so neither the build nor the tests need network access.
 *
 *   node scripts/build-openings.mjs
 *
 * Source: https://github.com/lichess-org/chess-openings (CC0-1.0). Their five
 * TSVs list an ECO code, a name and the moves for ~3,800 named lines.
 *
 * Openings are keyed by *position* rather than by move order. Two games that
 * arrive at the same position have played the same opening whatever route they
 * took, and transposing is ordinary — 1.Nf3 d5 2.d4 is a Queen's Pawn Game and
 * matching on the move list alone would miss it.
 *
 * The key is the EPD (a FEN without the clocks), produced by the same chess.js
 * that replays games in the app, so build-time and run-time keys agree.
 */
import { writeFileSync } from 'node:fs'
import { Chess } from 'chess.js'

const FILES = ['a', 'b', 'c', 'd', 'e']
const BASE = 'https://raw.githubusercontent.com/lichess-org/chess-openings/master'

/** FEN minus the halfmove clock and fullmove number. */
function epd(fen) {
  return fen.split(' ').slice(0, 4).join(' ')
}

const rows = []
for (const file of FILES) {
  const res = await fetch(`${BASE}/${file}.tsv`)
  if (!res.ok) throw new Error(`${file}.tsv: HTTP ${res.status}`)
  const lines = (await res.text()).trim().split('\n')
  if (lines.shift() !== 'eco\tname\tpgn') throw new Error(`${file}.tsv: unexpected header`)
  for (const line of lines) {
    const [eco, name, pgn] = line.split('\t')
    const chess = new Chess()
    for (const token of pgn.split(/\s+/)) {
      if (/^\d+\.+$/.test(token)) continue
      chess.move(token)
    }
    rows.push({ eco, name, epd: epd(chess.fen()), plies: chess.history().length })
  }
}

// A position naming two different openings would make the lookup order-
// dependent, so fail loudly rather than silently picking one.
const seen = new Map()
for (const row of rows) {
  const clash = seen.get(row.epd)
  if (clash && (clash.eco !== row.eco || clash.name !== row.name)) {
    throw new Error(`Two openings share a position: "${clash.name}" and "${row.name}"`)
  }
  seen.set(row.epd, row)
}

// Longest line first: the lookup walks the game backwards from its deepest
// position, so this only records how far back it is worth looking.
const maxPlies = Math.max(...rows.map((r) => r.plies))

const table = [...seen.values()].map((r) => `${r.epd}|${r.eco}|${r.name}`).join('\n')
const escaped = table.replace(/[\\`$]/g, '\\$&')

writeFileSync(
  new URL('../src/lib/openings.data.ts', import.meta.url),
  `/**
 * Generated by scripts/build-openings.mjs — do not edit by hand.
 *
 * The lichess opening book (https://github.com/lichess-org/chess-openings,
 * CC0-1.0), one line per opening: EPD|ECO|name.
 *
 * Kept as a string rather than an object literal because it is parsed once,
 * lazily, into a Map; ${seen.size.toLocaleString('en-US')} object literals would cost far more to
 * parse than one string does.
 */

/** Deepest book line, in plies. */
export const MAX_BOOK_PLIES = ${maxPlies}

export default \`${escaped}\`
`,
  'utf-8',
)

console.log(`${seen.size} openings, deepest ${maxPlies} plies, ${table.length} chars`)
